def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = set(v for row in grid for v in row)
    bg = max(colors, key=lambda c: sum(v == c for row in grid for v in row))
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    col = grid[r1][c1]
                    if col == bg:
                        continue
                    if any(grid[r1][c] != col or grid[r2][c] != col for c in range(c1, c2 + 1)):
                        continue
                    if any(grid[r][c1] != col or grid[r][c2] != col for r in range(r1, r2 + 1)):
                        continue
                    if all(grid[r][c] == bg for r in range(r1 + 1, r2) for c in range(c1 + 1, c2)):
                        # Cavities with even height and width map to 2;
                        # otherwise they map to 7.
                        ih, iw = r2 - r1 - 1, c2 - c1 - 1
                        fill = 2 if ih % 2 == 0 and iw % 2 == 0 else 7
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                out[r][c] = fill
    return out
